using System;
using System.Collections;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Evil Soul Heat", menuName = "Data/Battle/Effects/Enemy/Evil Soul Heat")]
public class EvilSoulHeat : ScriptableObject
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	[Header("Soul Heat Event")]
	[SerializeField]
	private VoidEvent OnUpdateEvilSoulHeatHUD;

	[NonSerialized]
	[ShowNonSerializedField]
	private int evilSoulHeatCounter;

	public int EvilSoulHeatCounter => evilSoulHeatCounter;

	public int EvilSoulHeatMaxCounter => soulHeat.MaxSoulHeat;

	public void ModifyEvilSoulHeat(int amount)
	{
		int num = evilSoulHeatCounter;
		evilSoulHeatCounter += amount;
		evilSoulHeatCounter = Mathf.Clamp(evilSoulHeatCounter, 0, EvilSoulHeatMaxCounter);
		if (num != evilSoulHeatCounter)
		{
			ActivateOnSoulHeatHitValueEffects();
			OnUpdateEvilSoulHeatHUD.Raise();
		}
	}

	private void ActivateOnSoulHeatHitValueEffects()
	{
		if (evilSoulHeatCounter == EvilSoulHeatMaxCounter)
		{
			ReferenceSingleton<BattleHandler>.Instance.CorruptedSoulActivated = true;
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetEvilSoulHeatAction(EndPlayerTurn());
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
	}

	private IEnumerator EndPlayerTurn()
	{
		yield return InvokeAlternatives.WaitForFrames(ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1);
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState);
		ReferenceSingleton<BattleHandler>.Instance.CorruptedSoulActivated = false;
	}

	[Button(null)]
	public void ResetSoulHeat()
	{
		if (evilSoulHeatCounter != 0)
		{
			evilSoulHeatCounter = 0;
			ActivateOnSoulHeatHitValueEffects();
			OnUpdateEvilSoulHeatHUD.Raise();
		}
	}
}
